def page(title,body,pre=''):
 return f'<!doctype html><html lang="en" data-theme="light"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="Achraf RAHIBE, UAV and avionics systems engineer. Aircraft, ground robotics, surface vessels, integration and technical documentation."><title>{e(title)} | Achraf RAHIBE</title><link rel="stylesheet" href="{pre}assets/site.css?v=20261026-library4"></head><body>{nav(pre)}{body}{footer(pre)}<script src="{pre}assets/site.js?v=20261026-library4" defer></script></body></html>'
def photo(d,pre='',kind='cover'):
 if d.get('image') and d.get('photo_verified'):
  return f'<div class="{kind}"><img src="{pre}{d["image"]}" alt="{e(d["title"])} project photograph" loading="lazy"></div>'
 return f'<div class="{kind}"><div class="photo-pending" aria-label="Project photograph pending">Project photo to be added</div></div>'

def project_media(d,pre):
 if d['id']!='vtol':return ''
 lib=json.loads((ROOT/'content/vtol-media.json').read_text(encoding='utf8'))
 videos=''.join('<figure class="video-card"><video controls playsinline controlslist="nodownload noremoteplayback" disablepictureinpicture preload="none" poster="'+pre+v['poster']+'" aria-label="'+e(v['title'])+'"><source src="'+pre+v['file']+'" type="video/mp4">Your browser does not support inline video playback.</video><figcaption><strong>'+e(v['title'])+'</strong><span>'+e(v['date'])+' · '+str(v['duration'])+' seconds</span><span>'+e(v.get('caption',''))+'</span></figcaption></figure>' for v in lib['videos'])
 reports=''.join('<article class="report-card"><h3>'+e(r['title'])+'</h3><p>'+e(r['note'])+'</p><div class="links"><a href="'+pre+r['file']+'" target="_blank" rel="noopener">Open PDF</a><a href="'+pre+r['file']+'" download>Download PDF</a></div><details><summary>Read PDF on this page</summary><iframe loading="lazy" src="'+pre+r['file']+'#view=FitH" title="'+e(r['title'])+'"></iframe></details></article>' for r in lib['reports'])
 return '<section class="section" id="flight-recordings"><div class="section-title"><h2>Selected flight recordings</h2><span class="count">3 selected flight excerpts</span></div><p class="section-note">Two airborne hover excerpts and one stability-investigation sequence. I supported the on-site team through live calls during testing, alongside configuration and log review. Clips are muted web excerpts; originals remain in the private project archive.</p><div class="video-grid">'+videos+'</div></section><section class="section" id="report-library"><div class="section-title"><h2>Project report library</h2></div><p class="section-note">My engineering analyses are separated from the third-party aircraft reference. These are historical project work samples, not universal setup instructions.</p><div class="report-grid">'+reports+'</div></section><section class="section"><div class="section-title"><h2>Configuration reference</h2></div><figure class="motor-diagram"><img src="'+pre+'media/vtol/motor-layout.png" alt="Reference diagram showing quad motor numbering and rotation directions"><figcaption>Supplied motor-layout reference diagram. A configuration aid, not an aircraft photograph or a standalone installation instruction.</figcaption></figure><figure class="motor-diagram"><img src="'+pre+'media/vtol/pixhawk-wiring-reference.jpg" alt="Pixhawk 6C sample wiring reference from Holybro"><figcaption>Third-party reference: Holybro Pixhawk 6C sample wiring diagram. Not an as-built drawing of this aircraft.</figcaption></figure></section>'

def card(d,pre=''):
 return f'''<article class="project" data-project data-domain="{d['domain']}" data-search="{e(' '.join([d['title'],d['contribution']]+d['tags']))}"><a href="{pre}projects/{d['id']}/">{photo(d,pre)}<div class="project-body"><p class="meta">{e(labels[d['domain']])} · {e(d['status'])}</p><h3>{e(d['title'])}</h3><p class="summary">{e(d['problem'])}</p><span class="more">View project →</span></div></a></article>'''
def doc(p,pre=''):
 return f'''<a class="doc" href="{pre}technical-notes/{p['id']}/"><img src="{pre}{p['images'][0]}" alt="{e(p['title'])} report excerpt" loading="lazy"><div><p class="meta">Technical work sample</p><h3>{e(p['title'])}</h3><p>{e(p['subtitle'])}</p><span class="more">Read document →</span></div></a>'''

